package com.vandorlabs.neoforge.client;
import com.vandorlabs.neoforge.screen.*;
import com.vandorlabs.neoforge.redstone.NativeLoadedRedstonePower;
import com.vandorlabs.screen.*;
import net.minecraft.client.Minecraft;
import net.minecraft.client.multiplayer.ClientLevel;
import net.minecraft.core.BlockPos;
import net.minecraft.world.level.chunk.status.ChunkStatus;
import java.util.*;
/** Main-thread prepared projection. Mesh workers consume the returned immutable Visual only. */
@net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs",value=net.neoforged.api.distmarker.Dist.CLIENT)
public final class NativeScreenClientPower {
 private NativeScreenClientPower(){}
 public static final int SIGNAL=ScreenPowerQueries.SIGNAL,STATE=ScreenPowerQueries.STATE,EFFECTIVE_MODE=ScreenPowerQueries.EFFECTIVE_MODE,SURFACE_0=ScreenPowerQueries.SURFACE_0,SURFACE_1=ScreenPowerQueries.SURFACE_1,MODE_0=ScreenPowerQueries.MODE_0,MODE_1=ScreenPowerQueries.MODE_1,SPEED_0=ScreenPowerQueries.SPEED_0,SPEED_1=ScreenPowerQueries.SPEED_1,OVERRIDES=ScreenPowerQueries.OVERRIDES,SPLIT=ScreenPowerQueries.SPLIT,PRIMARY_ARTWORK=ScreenPowerQueries.PRIMARY_ARTWORK,ANIMATION_SPEED=ScreenPowerQueries.ANIMATION_SPEED,ALL=ScreenPowerQueries.ALL;
 private static final int MAX_WATCHED=256;private static final Map<ClientLevel,Epoch> LEVELS=new WeakHashMap<>();
 private static final class Watch{int mask;long seen;Watch(int mask,long seen){this.mask=mask;this.seen=seen;}}
 private static final class Epoch{volatile long revision;long tick,observedTime=Long.MIN_VALUE;final Map<NativeScreenEntity,Watch> watched=new WeakHashMap<>();}
 static{NativeScreenPowerViews.bindClient(NativeScreenClientPower::invalidate);}
 @net.neoforged.fml.common.EventBusSubscriber(modid="vandorlabs",value=net.neoforged.api.distmarker.Dist.CLIENT,bus=net.neoforged.fml.common.EventBusSubscriber.Bus.MOD)public static final class Binding{@net.neoforged.bus.api.SubscribeEvent public static void setup(net.neoforged.fml.event.lifecycle.FMLClientSetupEvent event){NativeScreenPowerViews.bindClient(NativeScreenClientPower::invalidate);}}
 private static Epoch epoch(ClientLevel level){synchronized(LEVELS){return LEVELS.computeIfAbsent(level,ignored->new Epoch());}}
 private static void advance(Epoch state,ClientLevel level){long now=level.getGameTime();if(state.observedTime!=now){state.observedTime=now;state.tick++;}}
 private static void invalidate(NativeScreenEntity tile){if(!(tile.getLevel() instanceof ClientLevel level))return;var state=epoch(level);synchronized(state){state.revision++;}var view=tile.preparedPowerView();if(view!=null)view.invalidate();}
 private static void mainThread(){if(!Minecraft.getInstance().isSameThread())throw new IllegalStateException("Screen power preparation requires the client thread");}
 private static boolean installed(ClientLevel level,NativeScreenEntity tile){if(tile.inert()||tile.isRemoved()||tile.getLevel()!=level)return false;var pos=tile.getBlockPos();var chunk=level.getChunkSource().getChunk(pos.getX()>>4,pos.getZ()>>4,ChunkStatus.FULL,false);return chunk!=null&&chunk.getBlockEntities().get(pos)==tile&&chunk.getBlockState(pos)==tile.getBlockState()&&tile.getBlockState().getBlock() instanceof NativeScreenBlock block&&block.family()==tile.family();}

 private static boolean grouped(NativeScreenEntity tile){var s=tile.screenSettings();int mode=s.activation().data().mode<0?(s.scalar().redstoneEnabled?1:0):s.activation().data().mode;return mode>0&&ScreenJoinGeometry.supports(tile.family(),s.scalar().smallInput);}
 public static NativeScreenEntity.Visual prepare(NativeScreenEntity tile,int mask){mainThread();if((mask&~ALL)!=0||mask<0)throw new IllegalArgumentException("Screen getter mask");if(!(tile.getLevel() instanceof ClientLevel level)||Minecraft.getInstance().level!=level||!installed(level,tile))return tile.visual();var state=epoch(level);advance(state,level);boolean needed=ScreenPowerQueries.needsPhysical(tile.preparedPowerQueries(),mask);if(needed){sample(level,tile,state);if(grouped(tile)){synchronized(state){var old=state.watched.get(tile);if(old!=null){old.mask=old.seen==state.tick?old.mask|mask:mask;old.seen=state.tick;}else if(state.watched.size()<MAX_WATCHED)state.watched.put(tile,new Watch(mask,state.tick));}}}else synchronized(state){var old=state.watched.get(tile);if(old!=null&&old.seen!=state.tick)state.watched.remove(tile);}return tile.visual();}
 private static final class Group implements NativeScreenPowerView {
  final List<NativeScreenEntity> members;final Epoch epoch;final long revision;final net.minecraft.world.level.block.state.BlockState state;long tick=Long.MIN_VALUE;boolean invalid;int power;
  Group(List<NativeScreenEntity> members,Epoch epoch){this.members=new ArrayList<>(members);this.epoch=epoch;revision=epoch.revision;state=members.get(0).getBlockState();}
  public void invalidate(){invalid=true;members.clear();}
 }
 private static void sample(ClientLevel level,NativeScreenEntity tile,Epoch epoch){if(!grouped(tile)){publish(level,List.of(tile),NativeLoadedRedstonePower.level(level,tile.getBlockPos()));return;}var view=tile.preparedPowerView();Group group=view instanceof Group cached?cached:null;if(group==null||group.invalid||group.revision!=epoch.revision||group.state!=tile.getBlockState()){build(level,tile,epoch);group=(Group)tile.preparedPowerView();}if(group.tick==level.getGameTime())return;group.tick=level.getGameTime();int power=0;for(var member:group.members){if(!installed(level,member)||member.getBlockState()!=group.state){group.invalidate();epoch.revision++;build(level,tile,epoch);sample(level,tile,epoch);return;}power=Math.max(power,NativeLoadedRedstonePower.level(level,member.getBlockPos()));}group.power=power;publish(level,group.members,power);}
 private static void publish(ClientLevel level,List<NativeScreenEntity> members,int power){List<NativeScreenEntity> changed=null;for(var member:members)if(installed(level,member)&&member.installPreparedClientPower(power)){if(changed==null)changed=new ArrayList<>();changed.add(member);}if(changed!=null)for(var member:changed)level.getChunkSource().getLightEngine().checkBlock(member.getBlockPos());}
 private static void build(ClientLevel level,NativeScreenEntity origin,Epoch epoch){var block=(NativeScreenBlock)origin.getBlockState().getBlock();var state=origin.getBlockState();var visual=origin.visual();var catalog=NativeScreenCatalog.INSTANCE;var first=NativeScreenJoining.signature(visual.family(),visual.settings(),visual.frames(),visual.controls(),catalog);var signatures=new IdentityHashMap<NativeScreenEntity,ScreenJoinSignature>();signatures.put(origin,first);var access=new ScreenRectangleGroups.Access<NativeScreenEntity>(){public int x(NativeScreenEntity tile){return tile.getBlockPos().getX();}public int y(NativeScreenEntity tile){return tile.getBlockPos().getY();}public int z(NativeScreenEntity tile){return tile.getBlockPos().getZ();}public boolean loaded(int x,int y,int z){return level.getChunkSource().getChunk(x>>4,z>>4,ChunkStatus.FULL,false)!=null;}public NativeScreenEntity at(int x,int y,int z){var chunk=level.getChunkSource().getChunk(x>>4,z>>4,ChunkStatus.FULL,false);if(chunk==null)return null;var value=chunk.getBlockEntities().get(new BlockPos(x,y,z));return value instanceof NativeScreenEntity tile?tile:null;}public boolean compatible(NativeScreenEntity ignored,NativeScreenEntity next){if(!installed(level,next)||next.family()!=origin.family()||next.getBlockState()!=state)return false;var signature=signatures.computeIfAbsent(next,tile->{var value=tile.visual();return NativeScreenJoining.signature(value.family(),value.settings(),value.frames(),value.controls(),catalog);});return first.powerMatches(signature);}};var groups=ScreenRectangleGroups.discover(origin,ScreenJoinGeometry.basis(origin.family(),block.screenState(state),origin.screenSettings().ceilingMounted()),access,true);for(var rectangle:groups.rectangles){var group=new Group(rectangle,epoch);for(var member:rectangle)member.preparedPowerView(group);}}
 @net.neoforged.bus.api.SubscribeEvent public static void tick(net.neoforged.neoforge.client.event.ClientTickEvent.Post event){var mc=Minecraft.getInstance();if(mc.level==null||mc.isPaused())return;var level=mc.level;Epoch state;synchronized(LEVELS){state=LEVELS.get(level);}if(state==null)return;List<NativeScreenEntity> watched;synchronized(state){advance(state,level);watched=new ArrayList<>(state.watched.keySet());}for(var tile:watched){Watch watch;synchronized(state){watch=state.watched.get(tile);}if(watch==null)continue;if(state.tick-watch.seen>1||!installed(level,tile)||!grouped(tile)||!ScreenPowerQueries.needsPhysical(tile.preparedPowerQueries(),watch.mask)){synchronized(state){state.watched.remove(tile);}continue;}sample(level,tile,state);}}
 @net.neoforged.bus.api.SubscribeEvent public static void unload(net.neoforged.neoforge.event.level.LevelEvent.Unload event){if(event.getLevel() instanceof ClientLevel level)synchronized(LEVELS){LEVELS.remove(level);}}
}
